/**
 * Rewrite a favicon / OG / similar href so it points at the running preview server.
 * Published absolute URLs (CDN / SITE) often 404 locally; the same path under the
 * framed origin usually serves the file.
 */
export function localizePreviewAssetUrl(href: string, pageUrl: string): string {
  const value = href.trim();
  if (!value) return "";
  try {
    const page = new URL(pageUrl);
    const asset = new URL(value, pageUrl);
    if (asset.protocol !== "http:" && asset.protocol !== "https:") return value;
    if (asset.origin === page.origin) return asset.href;

    const base = previewBasePath(page.pathname);
    const path = asset.pathname;
    if (path.startsWith(base) || path.startsWith("/preview/")) {
      return new URL(path + asset.search + asset.hash, page.origin).href;
    }
    return new URL(path.replace(/^\//, "") + asset.search + asset.hash, page.origin + base).href;
  } catch {
